'use strict'

import fp from 'fastify-plugin';
import Handlebars from 'handlebars';
import promisedHandlebars from 'promised-handlebars';
import helper from './helper/index.js';
import { setSetting } from './setting.js';

async function handlebarsPlugin(fastify, opts) {

  // Перевірка, чи вже зареєстровано Handlebars
  if (!fastify.handlebars) {

    const handlebars = promisedHandlebars(Handlebars);

    // Реєстрація хелперів
    helper(handlebars);

    // Додавання Handlebars до fastify
    fastify.decorate('handlebars', handlebars);

    // Зберігаємо копію fastify
    const saveSetting = setSetting(fastify);
    if (!saveSetting) {
      console.warn('@opengis/fastify-hb: Failed to save Fastify instance in settings.');
    }
  } else {
    console.warn('@opengis/fastify-hb: Handlebars is already registered.');
  }
}

export default fp(handlebarsPlugin);
